const usedExercises = `-- name: UsedExercises :many
SELECT e.id, e.name, e.aliases, e.measurement, e.unilateral, (e.user_id IS NOT NULL)::boolean AS custom,
    count(we.id)::bigint AS times
FROM exercises e
LEFT JOIN workout_exercises we ON we.exercise_id = e.id AND we.user_id = $1 AND we.deleted_at IS NULL
WHERE e.deleted_at IS NULL AND (e.user_id = $1 OR e.user_id IS NULL)
GROUP BY e.id
HAVING count(we.id) > 0 OR e.user_id IS NOT NULL
ORDER BY count(we.id) DESC, e.name
`

type UsedExercisesRow struct {
	ID          uuid.UUID
	Name        string
	Aliases     []string
	Measurement string
	Unilateral  bool
	Custom      bool
	Times       int64
}

// The exercises a user has logged, most-used first, plus their own never-used ones.
func (q *Queries) UsedExercises(ctx context.Context, userID uuid.UUID) ([]UsedExercisesRow, error) {
	rows, err := q.db.Query(ctx, usedExercises, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsedExercisesRow
	for rows.Next() {
		var i UsedExercisesRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Aliases,
			&i.Measurement,
			&i.Unilateral,
			&i.Custom,
			&i.Times,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

